def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp_bids = []
    wealthy_pressure = []

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_opp_bids.append(float(bid))
                if opp.get('budget', 0) > budget:
                    wealthy_pressure.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    slots = supply / float(WATER_REQ)
    contested = slots < (len(alive) + 1)
    high_supply = supply >= 23
    low_supply = supply <= 17

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else 0.0
    wealthy_prev = max(wealthy_pressure) if wealthy_pressure else 0.0

    if hp <= 2 or no_water_days >= 2:
        target = max(86.0, min(98.0, highest_prev + 2.0))
        if urgent_prev > 0:
            target = max(target, urgent_prev + 2.0)
        return float(min(budget, target))

    if hp <= 4 or no_water_days >= 1:
        if low_supply:
            target = max(84.5, min(96.0, max(urgent_prev, wealthy_prev, 82.5) + 2.0))
        else:
            target = max(72.0, min(88.0, max(urgent_prev, 70.0) + 1.5))
        return float(min(budget, target))

    if high_supply and hp >= 7:
        return float(min(budget, 24.0))

    if contested:
        base = 58.0
        if highest_prev >= 120.0:
            base = 52.0
        elif highest_prev >= 84.0:
            base = 66.0
        elif highest_prev >= 70.0:
            base = highest_prev + 1.5
        if low_supply:
            base += 6.0
        return float(min(budget, base))

    return float(min(budget, 32.0))
